// Worker entry: handles /api/* and hands everything else to the static assets.
// Hot or Cold's secret words, generated by scripts/word-list/build.mjs. Only the worker sees them.
import WORDS from './words.json'

const MAX_IMAGE_BYTES = 2 * 1024 * 1024

// Score levels, low to high. Jev returns the level index (0-4); the client shows it as 1-5.
const HOG_LEVELS = [
  'Not even an animal.',
  'Maybe an animal, but not a pig.',
  'Clearly a pig, but not drawn very well.',
  'An okay drawing of a pig, given that it was done using a mouse and keyboard.',
  'An actually decently good drawing of a pig.',
]

// Score sent back when Jev thinks the drawing inappropriate  
const NOT_A_PIG_SCORE = -1

async function rateHog(request, env) {
  if (request.method !== 'POST') return new Response(null, { status: 405 })
  if (request.headers.get('Content-Type') !== 'image/png') return new Response(null, { status: 415 })

  const image = await request.arrayBuffer()
  if (image.byteLength === 0 || image.byteLength > MAX_IMAGE_BYTES) return new Response(null, { status: 413 })

  const ref = crypto.randomUUID()
  const body = new FormData()
  body.append('request', new Blob([JSON.stringify({
    model: 'jev-latest',
    state: { drawing: ref },
    assets: { [ref]: { type: 'image', part: 'drawing' } },
    questions: {
      is_inappropriate: {
        type: 'noul',
        instructions: 'Is `drawing` phallic (including typical simple/crude penis sketches), and/or does it include a penis anywhere (even hidden away), and/or does it imply a phallus, and/or is it in any way otherwise inappropriate?',
      },
      is_automated_drawing: {
        type: 'noul',
        instructions: 'Is `drawing` created using automated software and is not handdrawn (e.g., clearly too straight lines or perfect ovals, or very symmetrical, or tool assisted, etc.)?',
      },
      hog: {
        type: 'score',
        instructions: 'How good a drawing of a pig is `drawing`?',
        criteria: HOG_LEVELS,
      },
    },
  })], { type: 'application/json' }))
  body.append('drawing', new Blob([image], { type: 'image/png' }), 'drawing.png')

  const res = await fetch('https://api.typesafe.ai/v1/systemone', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${env.TYPESAFE_API_KEY}`,
      'TypeSafe-Danger-Zone-Images': 'true',
    },
    body,
  })
  if (!res.ok) {
    console.error('Jev request failed', res.status, await res.text())
    return new Response(null, { status: 502 })
  }

  const { answers } = await res.json()
  // noul is the probability (0-1) that the answer is yes.
  if (answers.is_inappropriate.noul > 0.50) return Response.json({ score: NOT_A_PIG_SCORE })
  return Response.json({ score: answers.hog.score + 1, automated: answers.is_automated_drawing.noul > 0.50 })
}

// Closeness levels, cold to hot. Jev returns the level index (0-6), sent back shifted to -1 to +1.
function closenessLevels(word) {
  return [
    `Depicts the entire opposite concept to "${word}".`,
    `Depicts something strongly contrasting with "${word}".`,
    `Depicts something leaning away from "${word}".`,
    `Unclear, or depicts a concept entirely tangential to "${word}".`,
    `Depicts the same broad kind of thing as "${word}" (e.g. any animal when the word is "frog"), or something loosely related to it.`,
    `Depicts something closely related or very similar to "${word}" (e.g. a toad when the word is "frog"), but not "${word}" itself.`,
    `Depicts exactly "${word}".`,
  ]
}
const MIDDLE_LEVEL = 3

// The browser holds the word only as a token encrypted with a key derived from the API key, so
// the player can't read it but the worker stays stateless.
async function wordKey(env) {
  const encoder = new TextEncoder()
  const secret = await crypto.subtle.importKey('raw', encoder.encode(env.TYPESAFE_API_KEY), 'HKDF', false, ['deriveKey'])
  return crypto.subtle.deriveKey(
    { name: 'HKDF', hash: 'SHA-256', salt: new Uint8Array(), info: encoder.encode('hot-or-cold word') },
    secret, { name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt'],
  )
}

async function encryptWord(word, env) {
  const iv = crypto.getRandomValues(new Uint8Array(12))
  const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, await wordKey(env), new TextEncoder().encode(word))
  const bytes = new Uint8Array([...iv, ...new Uint8Array(ciphertext)])
  return btoa(String.fromCharCode(...bytes)).replaceAll('+', '-').replaceAll('/', '_').replaceAll('=', '')
}

// Returns null for a missing or tampered token.
async function decryptWord(token, env) {
  try {
    const bytes = Uint8Array.from(atob(token.replaceAll('-', '+').replaceAll('_', '/')), c => c.charCodeAt(0))
    const plaintext = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: bytes.slice(0, 12) }, await wordKey(env), bytes.slice(12))
    return new TextDecoder().decode(plaintext)
  } catch {
    return null
  }
}

const isLetter = char => /\p{L}/u.test(char)

// A seeded random number generator (mulberry32), returning floats in [0, 1).
function seededRandom(seed) {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

// The order letters are revealed in: the word's letter positions shuffled, seeded by (an FNV-1a
// hash of) the word itself, so every score for the same word reveals letters in the same order.
function revealOrder(word) {
  const chars = [...word]
  let hash = 2166136261
  for (const char of chars) hash = Math.imul(hash ^ char.codePointAt(0), 16777619)
  const random = seededRandom(hash)
  const positions = chars.flatMap((char, i) => (isLetter(char) ? [i] : []))
  for (let i = positions.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1))
    ;[positions[i], positions[j]] = [positions[j], positions[i]]
  }
  return positions
}

// The word with `shown` letters showing, in reveal order, and the rest blanked out ("f_o_").
// Spaces and hyphens always show.
function blankedOut(word, shown) {
  const visible = new Set(revealOrder(word).slice(0, shown))
  return [...word].map((char, i) => (isLetter(char) && !visible.has(i) ? '_' : char)).join('')
}

// The first letter shows at a score of REVEAL_FROM and the last at REVEAL_ALL, with the thresholds
// for the rest spread evenly between, so each threshold crossed reveals one more letter. The player
// wins once every letter shows.
const REVEAL_FROM = 0.2
const REVEAL_ALL = 0.8

function lettersRevealed(word, score) {
  if (score < REVEAL_FROM) return 0
  const letters = [...word].filter(isLetter).length
  // The epsilon stops floating point error landing a score that's exactly on a threshold, like 0.6, just under it.
  return Math.min(letters, 1 + Math.floor(((score - REVEAL_FROM) * (letters - 1)) / (REVEAL_ALL - REVEAL_FROM) + 1e-9))
}

// The category and the blanked-out word are the hints shown from the start.
async function newWord(request, env) {
  if (request.method !== 'POST') return new Response(null, { status: 405 })
  const { word, category } = WORDS[Math.floor(Math.random() * WORDS.length)]
  return Response.json({ token: await encryptWord(word, env), category, pattern: blankedOut(word, 0) })
}

// Give up: hands back the word behind a token.
async function revealWord(request, env) {
  if (request.method !== 'POST') return new Response(null, { status: 405 })
  const word = await decryptWord(request.headers.get('X-Word-Token') ?? '', env)
  if (word === null) return new Response(null, { status: 400 })
  return Response.json({ word })
}

async function hotOrCold(request, env) {
  if (request.method !== 'POST') return new Response(null, { status: 405 })
  if (request.headers.get('Content-Type') !== 'image/png') return new Response(null, { status: 415 })

  const word = await decryptWord(request.headers.get('X-Word-Token') ?? '', env)
  if (word === null) return new Response(null, { status: 400 })

  const image = await request.arrayBuffer()
  if (image.byteLength === 0 || image.byteLength > MAX_IMAGE_BYTES) return new Response(null, { status: 413 })

  const ref = crypto.randomUUID()
  const body = new FormData()
  body.append('request', new Blob([JSON.stringify({
    model: 'jev-latest',
    state: { drawing: ref },
    assets: { [ref]: { type: 'image', part: 'drawing' } },
    questions: {
      closeness: {
        type: 'score',
        instructions: `You are playing reverse pictionary with a player. You know the secret word "${word}" and must help the player figure it out. The player can only communicate via drawings, and you can only communicate back by ranking how close \`drawing\` is to the secret word. Only judge what is drawn; written words or letters do not count.`,
        criteria: closenessLevels(word),
      },
    },
  })], { type: 'application/json' }))
  body.append('drawing', new Blob([image], { type: 'image/png' }), 'drawing.png')

  const res = await fetch('https://api.typesafe.ai/v1/systemone', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${env.TYPESAFE_API_KEY}`,
      'TypeSafe-Danger-Zone-Images': 'true',
    },
    body,
  })
  if (!res.ok) {
    console.error('Jev request failed', res.status, await res.text())
    return new Response(null, { status: 502 })
  }

  const { answers } = await res.json()
  const score = (answers.closeness.score - MIDDLE_LEVEL) / MIDDLE_LEVEL
  return Response.json({ score, pattern: blankedOut(word, lettersRevealed(word, score)) })
}

export default {
  async fetch(request, env) {
    const { pathname } = new URL(request.url)
    if (pathname === '/api/rate-hog') return rateHog(request, env)
    if (pathname === '/api/hot-or-cold') return hotOrCold(request, env)
    if (pathname === '/api/hot-or-cold/new-word') return newWord(request, env)
    if (pathname === '/api/hot-or-cold/reveal') return revealWord(request, env)
    return env.ASSETS.fetch(request)
  },
}
